sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    // Script created as part of MSSCUSTODY3120
    //Validating assignment Group
    var currentUserAssignmentGroups;
    var ga = new GlideAjax('GetUserAssignmentGroups');
    ga.addParam('sysparm_name', 'getUserAssignmentGroups');
    ga.addParam('sysparm_assignmentgroup', g_form.getValue('assignment_group'));
    ga.addParam('sysparm_recordSysID', g_form.getUniqueValue()); // Script updated as part of MSSCUSTODY2922
    ga.getXML(Updategroup);

    function Updategroup(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");
        currentUserAssignmentGroups = answer.split(',');
        if (currentUserAssignmentGroups.length > 1) {
            g_form.clearValue('assignment_group');
            g_form.setMandatory('assignment_group', true);

        } else {
            g_form.setValue('assignment_group', currentUserAssignmentGroups);
        }


        //Storing current values of assigned to and assignment group
        //Updating the assigned to attribute
        var currentAssignedTo = g_form.getValue('assigned_to');
        var assignGroupId = g_form.getValue('assignment_group');

        //condition to validate whether assigned to is empty
        //	if (currentAssignedTo == '') {
        var grAjaxUser = new GlideAjax('x_hsb11_mss_c_proc.HSBCTradeTaskUtils'); //calling script include here
        grAjaxUser.addParam('sysparm_name', 'LoggedUserAssigned');
        grAjaxUser.addParam('sysparm_grpID', assignGroupId);
        grAjaxUser.getXML(AutopopulateAssignTo);
        //    }
        function AutopopulateAssignTo(response) {
            var currentUserId = response.responseXML.documentElement.getAttribute("answer");
            // Added validation to make sure maker user is not making the checker decision
            if (currentUserId == g_form.getValue('trade_case_id.current_maker_assignee'))
                alert('Checker cannot be the same user who actioned the maker task');
            else
            if (typeof(g_aw) != 'undefined') { //added to fix MSSCUSTODY-6451
                g_form.setValue('assigned_to', ''); 
                g_form.setValue('assigned_to', currentUserId);
            } else {
                g_form.setValue('assigned_to', currentUserId);
            }

        }
    }

}
